-- Schema ER_DIAGRAM.drawio: UUID generated by JPA; no cascading deletes.

CREATE TABLE cliente (
    id uuid PRIMARY KEY,
    user_id uuid UNIQUE REFERENCES app_user(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    indirizzo varchar(255),
    cap varchar(16),
    codice_fiscale varchar(16),
    partita_iva varchar(20),
    pec varchar(254),
    data_nascita date,
    nome varchar(100) NOT NULL CHECK (btrim(nome) <> ''),
    cognome varchar(100) NOT NULL CHECK (btrim(cognome) <> ''),
    iban varchar(100),
    indirizzo_fatturazione varchar(255)
);

CREATE TABLE impianto (
    id uuid PRIMARY KEY,
    id_tipo_impianto uuid NOT NULL REFERENCES tipo_impianto(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    indirizzo varchar(255) NOT NULL CHECK (btrim(indirizzo) <> ''),
    cap varchar(16) NOT NULL CHECK (btrim(cap) <> ''),
    nome varchar(150) NOT NULL CHECK (btrim(nome) <> ''),
    descrizione text,
    numero_sim text,
    codice_sim text,
    longitudine numeric(9,6),
    latitudine numeric(9,6),
    comune varchar(255) NOT NULL CHECK (btrim(comune) <> '')
);

CREATE INDEX ix_impianto_id_tipo_impianto ON impianto(id_tipo_impianto);

CREATE TABLE cliente_impianto (
    id uuid PRIMARY KEY,
    id_cliente uuid NOT NULL REFERENCES cliente(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_impianto uuid NOT NULL REFERENCES impianto(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT uq_cliente_impianto UNIQUE (id_cliente, id_impianto)
);

CREATE INDEX ix_cliente_impianto_id_impianto ON cliente_impianto(id_impianto);

CREATE TABLE articolo (
    id uuid PRIMARY KEY,
    id_tipo_articolo uuid NOT NULL REFERENCES tipo_articolo(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_impianto uuid REFERENCES impianto(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    matricola varchar(100),
    stato varchar(32) NOT NULL CHECK (btrim(stato) <> ''),
    CHECK (matricola IS NULL OR btrim(matricola) <> '')
);

CREATE INDEX ix_articolo_id_tipo_articolo ON articolo(id_tipo_articolo);
CREATE INDEX ix_articolo_id_impianto ON articolo(id_impianto);

CREATE TABLE assistenza (
    id uuid PRIMARY KEY,
    id_articolo uuid NOT NULL REFERENCES articolo(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_tipo_assistenza uuid NOT NULL REFERENCES tipo_assistenza(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    data_inizio date NOT NULL,
    data_fine date NOT NULL,
    note text,
    CHECK (data_fine > data_inizio)
);

CREATE INDEX ix_assistenza_id_articolo ON assistenza(id_articolo);
CREATE INDEX ix_assistenza_id_tipo_assistenza ON assistenza(id_tipo_assistenza);

CREATE TABLE intervento (
    id uuid PRIMARY KEY,
    id_impianto uuid NOT NULL REFERENCES impianto(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_tipo_intervento uuid NOT NULL REFERENCES tipo_intervento(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_assistenza uuid REFERENCES assistenza(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    data timestamptz NOT NULL,
    note text,
    esito text
);

CREATE INDEX ix_intervento_id_impianto ON intervento(id_impianto);
CREATE INDEX ix_intervento_id_tipo_intervento ON intervento(id_tipo_intervento);
CREATE INDEX ix_intervento_id_assistenza ON intervento(id_assistenza);

CREATE TABLE user_intervento (
    id uuid PRIMARY KEY,
    id_intervento uuid NOT NULL REFERENCES intervento(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_user uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT uq_user_intervento UNIQUE (id_user, id_intervento)
);

CREATE INDEX ix_user_intervento_id_intervento ON user_intervento(id_intervento);

CREATE TABLE bolla (
    id uuid PRIMARY KEY,
    id_fornitore uuid REFERENCES fornitore(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    numero_bolla varchar(100) NOT NULL CHECK (btrim(numero_bolla) <> ''),
    data_bolla date NOT NULL,
    data_arrivo date,
    direzione varchar(8) NOT NULL CHECK (btrim(direzione) <> '' AND direzione IN ('ARRIVO', 'USCITA'))
);

CREATE INDEX ix_bolla_id_fornitore ON bolla(id_fornitore);

CREATE TABLE bolla_tipo_articolo (
    id uuid PRIMARY KEY,
    id_bolla uuid NOT NULL REFERENCES bolla(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    id_tipo_articolo uuid NOT NULL REFERENCES tipo_articolo(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    quantita integer NOT NULL CHECK (quantita >= 1),
    CONSTRAINT uq_bolla_tipo_articolo UNIQUE (id_bolla, id_tipo_articolo)
);

CREATE INDEX ix_bolla_tipo_articolo_id_tipo_articolo ON bolla_tipo_articolo(id_tipo_articolo);


